[
  {
    "statement": "Evidence specific to wild bees is currently lacking.",
    "citations": [
      "36"
    ]
  },
  {
    "statement": "A review of the action to retain dead wood in forests or woodlands reported that no studies were found which directly and quantitatively tested the impact on wild bee communities or populations.",
    "citations": [
      "36"
    ]
  },
  {
    "statement": "The effectiveness of retaining dead wood for wild bee communities or populations could not be assessed.",
    "citations": [
      "36"
    ]
  }
]

[
  {
    "statement": "There is no evidence available on the effects of reintroducing laboratory-reared bumblebee queens to the wild.",
    "citations": [
      "51"
    ]
  },
  {
    "statement": "No studies were found that directly and quantitatively test the reintroduction of laboratory-reared bumblebee queens to the wild.",
    "citations": [
      "51"
    ]
  }
]

[
  {
    "statement": "Fourteen trials recorded substantial numbers of wild bees foraging on sown flowering plants on farmland.",
    "citations": [
      "17"
    ]
  },
  {
    "statement": "Phacelia patches attracted substantial numbers of wild bees in most trials, with 8–35 foraging species recorded.",
    "citations": [
      "17"
    ]
  },
  {
    "statement": "One replicated trial in Greece found phacelia was not attractive to wild bees.",
    "citations": [
      "17"
    ]
  },
  {
    "statement": "Planted perennial leguminous herbs were more attractive to bumblebees in more arable landscapes.",
    "citations": [
      "17"
    ]
  },
  {
    "statement": "Planted lupine patches in Nova Scotia apple orchards enhanced the reproductive success of the bee species Osmia lignaria.",
    "citations": [
      "17"
    ]
  },
  {
    "statement": "One Dutch trial found no increase in bee numbers or species richness at a distance of 50 to 1,500 meters from planted patches.",
    "citations": [
      "17"
    ]
  },
  {
    "statement": "Two German trials found few solitary bees nesting on set-aside fields that were sown with phacelia or clover.",
    "citations": [
      "17"
    ]
  },
  {
    "statement": "Uncropped grassy field margins of 6 meters showed mixed outcomes for wild bee populations.",
    "citations": [
      "14"
    ]
  },
  {
    "statement": "One replicated controlled UK trial found higher wild bee abundance but not higher diversity at field boundaries with uncropped grassy margins.",
    "citations": [
      "14"
    ]
  },
  {
    "statement": "Another trial found higher abundance and diversity of bumblebees within uncropped grassy margins.",
    "citations": [
      "14"
    ]
  },
  {
    "statement": "A third smaller trial found no increases in wild bee populations in uncropped grassy margins.",
    "citations": [
      "14"
    ]
  },
  {
    "statement": "Evidence for the effect of organic arable farming on wild bees is equivocal.",
    "citations": [
      "25"
    ]
  },
  {
    "statement": "Three replicated trials reported higher wild bee abundance on organic farms.",
    "citations": [
      "25"
    ]
  },
  {
    "statement": "One of these trials also reported higher wild bee diversity in organically farmed wheat and adjacent mown fallows.",
    "citations": [
      "25"
    ]
  },
  {
    "statement": "Three other trials found no significant differences in bee numbers, species, or visitation between organic and conventional farms.",
    "citations": [
      "25"
    ]
  },
  {
    "statement": "There is no captured evidence that increasing clover leys enhances wild bee populations.",
    "citations": [
      "16"
    ]
  },
  {
    "statement": "One replicated German trial found that a white clover–grass mix did not attract solitary bees to nest preferentially.",
    "citations": [
      "16"
    ]
  },
  {
    "statement": "A Swiss trial showed that avoiding the use of a mower processor during clover flowering reduces bee injuries and mortality.",
    "citations": [
      "16"
    ]
  },
  {
    "statement": "There is no captured evidence that introducing nest boxes stocked with solitary bees has an effect on farmland wildlife.",
    "citations": [
      "81"
    ]
  },
  {
    "statement": "Rearing or managing solitary bees can increase local megachilid populations up to six-fold in one year when floral resources are plentiful.",
    "citations": [
      "54"
    ]
  },
  {
    "statement": "Parasites and pathogens are issues when rearing or managing solitary bees.",
    "citations": [
      "54"
    ]
  },
  {
    "statement": "Trials using artificial diets for solitary bees have had mixed survival outcomes.",
    "citations": [
      "54"
    ]
  },
  {
    "statement": "Wild bird cover mixtures often benefit invertebrates.",
    "citations": [
      "594"
    ]
  },
  {
    "statement": "Seven UK studies reported that wild bird cover mixtures had a higher abundance or species richness of butterflies and/or bees than other farmland habitats.",
    "citations": [
      "594"
    ]
  },
  {
    "statement": "Four other studies reported mixed or negative effects from wild bird cover mixtures.",
    "citations": [
      "594"
    ]
  },
  {
    "statement": "Invertebrate species showed preferences for specific plants within wild bird cover mixtures.",
    "citations": [
      "594"
    ]
  }
]

[
  {
    "statement": "No studies were found that directly tested the effects on wild bee communities of connecting areas of natural or semi-natural habitat for bees.",
    "citations": [
      "10"
    ]
  },
  {
    "statement": "Broader invertebrate evidence shows some colonization of corridors or restored habitat links.",
    "citations": [
      "579"
    ]
  },
  {
    "statement": "The results of invertebrate colonization of corridors or restored links are mixed across taxa.",
    "citations": [
      "579"
    ]
  },
  {
    "statement": "Slow colonization by invertebrates was reported in one case of a restored habitat link.",
    "citations": [
      "579"
    ]
  },
  {
    "statement": "Some wasp groups increased in connected habitat strips.",
    "citations": [
      "579"
    ]
  },
  {
    "statement": "Many ground beetles did not use connected habitat strips effectively.",
    "citations": [
      "579"
    ]
  },
  {
    "statement": "No studies were found that directly tested the effects of re-planting native forest on wild bee communities or populations.",
    "citations": [
      "35"
    ]
  },
  {
    "statement": "Along restored watercourses, bee visitation rates to native flowers were similar to those in remnant sites.",
    "citations": [
      "1408"
    ]
  },
  {
    "statement": "Along restored watercourses, the numbers of bees and bee species were similar to those in remnant sites.",
    "citations": [
      "1408"
    ]
  },
  {
    "statement": "Bee communities along restored watercourses differed from bee communities in remnant sites.",
    "citations": [
      "1408"
    ]
  },
  {
    "statement": "Plant-insect interactions along restored watercourses differed from those in remnant sites.",
    "citations": [
      "1408"
    ]
  },
  {
    "statement": "No studies were found demonstrating the effects of increasing or restoring natural or semi-natural habitat in farmed landscapes on bee diversity or abundance in neighbouring farms.",
    "citations": [
      "6"
    ]
  }
]

[
  {
    "statement": "The action documents do not report a percentage increase for bumblebee abundance when comparing native wildflower seed mixes with agricultural nectar/pollen mixes.",
    "citations": [
      "18",
      "19"
    ]
  },
  {
    "statement": "Three replicated trials found that agricultural forage plant mixes, including legumes, attracted greater numbers of bumblebees than a perennial wildflower mix, at least in the first year.",
    "citations": [
      "18"
    ]
  },
  {
    "statement": "One small replicated trial recorded that common long-tongued bumblebee species preferred perennial wildflower seed mix over a mix of annual forage plants.",
    "citations": [
      "19"
    ]
  }
]
